import { useStore } from '@tanstack/react-form'
import React from 'react'
import { type SmartFormFieldData, useFormContext } from './base'

// Use dependency fields
export const useDependencyFields = ({ fieldData }: { fieldData: SmartFormFieldData }) => {
  // Hooks
  const form = useFormContext()

  // States
  const [dependencyFieldCodes] = React.useState(() => {
    return (
      fieldData.config?.referenceFields?.reduce<string[]>((acc, field) => {
        if (fieldData.config?.apiPath?.includes(`{${field.code}}`)) {
          acc.push(field.code)
        }
        return acc
      }, []) ?? []
    )
  })

  // Form
  const dependencyFieldsValue = useStore(form.store, (state) =>
    dependencyFieldCodes.reduce<Record<string, string | null>>((acc, fieldCode) => {
      acc[fieldCode] = state.values[fieldCode]
      return acc
    }, {})
  )

  return {
    dependencyFieldCodes,
    dependencyFieldsValue
  }
}

// Extract dependencies
export const extractDependencies = (apiPath?: string): string[] => {
  if (!apiPath) return []

  const regex = /\{([^}]+)\}/g
  const deps: string[] = []

  let match: RegExpExecArray | null
  match = regex.exec(apiPath)
  while (match) {
    deps.push(match[1])
    match = regex.exec(apiPath)
  }

  return deps
}

// Build dependent graph
export type DependentGraph = ReturnType<typeof buildDependentGraph>
export const buildDependentGraph = (fields: SmartFormFieldData[]) => {
  const graph = new Map<string, string[]>()

  fields.forEach((field) => {
    const deps = extractDependencies(field.config?.apiPath)

    deps.forEach((dep) => {
      if (!graph.has(dep)) {
        graph.set(dep, [])
      }
      graph.get(dep)?.push(field.code)
    })
  })

  return graph
}

// Get all dependents
export const getAllDependents = (graph: Map<string, string[]>, fieldCode: string): string[] => {
  const result = new Set<string>()

  const dfs = (code: string) => {
    const dependents = graph.get(code) ?? []
    for (const dep of dependents) {
      if (!result.has(dep)) {
        result.add(dep)
        dfs(dep)
      }
    }
  }

  dfs(fieldCode)
  return Array.from(result)
}

import {
  type DefaultError,
  type GetNextPageParamFunction,
  type InfiniteData,
  type QueryKey,
  type UseInfiniteQueryResult,
  useInfiniteQuery,
  useQuery
} from '@tanstack/react-query'
import { useDebounce } from '@uidotdev/usehooks'
import React from 'react'
import { executeAxios } from '@/lib/axios'
import type { OptionsInfiniteQueryData, PaginationQueryData } from '@/types/api'
import type { Option } from '@/types/base'
import type { SmartFormFieldData } from './base'
import { useDependencyFields } from './dependency'

// Use options query
export const useOptionsQuery = ({ fieldData }: { fieldData: SmartFormFieldData }) => {
  // Hooks
  const { dependencyFieldCodes, dependencyFieldsValue } = useDependencyFields({ fieldData })

  // States
  const [apiPath, setApiPath] = React.useState(fieldData.config?.apiPath)
  const [isEnabled, setIsEnabled] = React.useState(!fieldData.config?.apiPath?.includes('/{'))

  // Queries
  const optionsQuery = useQuery<{
    responseData: {
      rows: Option[]
    }
  }>({
    queryKey: apiPath ? apiPath?.split('?') : [],
    queryFn: ({ signal }) => {
      return executeAxios({ url: apiPath, method: 'GET', signal })
    },
    enabled: isEnabled
  })

  // Effects
  React.useEffect(() => {
    if (!fieldData.config?.apiPath) {
      return
    }

    const newQueryPath = dependencyFieldCodes.reduce<string>((result, code) => {
      const value = dependencyFieldsValue[code]
      if (value == null) {
        return result
      }
      return result.replace(`{${code}}`, value)
    }, fieldData.config.apiPath)

    setApiPath(newQueryPath)
    setIsEnabled(!newQueryPath?.includes('/{'))
  }, [dependencyFieldCodes, dependencyFieldsValue, fieldData])

  // Memos
  const options = React.useMemo<Option[]>(() => {
    if (!isEnabled) {
      return []
    }
    return (
      optionsQuery.data?.responseData?.rows.map((option) => ({
        value: option.value,
        label: typeof option.label === 'string' ? option.label : JSON.stringify(option.label)
      })) ?? []
    )
  }, [isEnabled, optionsQuery.data])

  return {
    optionsQuery,
    options
  }
}

// Infinite query page size
export const infiniteQueryPageSize = 100

// Get next page param
export const getNextPageParam: GetNextPageParamFunction<number | undefined> = (queryFn, _, page) => {
  const {
    responseData: { count, pageSize }
  } = queryFn as unknown as PaginationQueryData
  const queryPage = page as unknown as number
  const totalPage = Math.ceil(count / pageSize)

  if (!totalPage || queryPage === totalPage) {
    return null
  }
  return queryPage + 1
}

// Fetch next page
export const fetchNextPage = (args: {
  event: React.UIEvent<HTMLDivElement, UIEvent>
  infiniteQuery: UseInfiniteQueryResult
}) => {
  // Args
  const { event, infiniteQuery } = args

  const { scrollTop, offsetHeight, scrollHeight } = event.target as HTMLDivElement
  if (
    scrollTop + offsetHeight >= scrollHeight - 32 * 20 &&
    !infiniteQuery.isFetchingNextPage &&
    infiniteQuery.hasNextPage
  ) {
    infiniteQuery.fetchNextPage()
  }
}

// Use options infinite query
export const useOptionsInfiniteQuery = ({
  fieldData,
  selectedValue,
  isLabelAsValue = false
}: {
  fieldData: SmartFormFieldData
  selectedValue: string | null | undefined // If value is array, separate by the "," character
  isLabelAsValue?: boolean
}) => {
  // Hooks
  const { dependencyFieldCodes, dependencyFieldsValue } = useDependencyFields({ fieldData })

  // States
  const [apiPath, setApiPath] = React.useState(fieldData.config?.apiPath)
  const [isEnabled, setIsEnabled] = React.useState(!fieldData.config?.apiPath?.includes('/{'))
  const [searchKeyword, setSearchKeyword] = React.useState('')

  // Debounced
  const debouncedSearchKeyword = useDebounce(isLabelAsValue ? selectedValue?.trim() : searchKeyword.trim(), 400)

  // Queries
  const optionsInfiniteQuery = useInfiniteQuery<
    OptionsInfiniteQueryData,
    DefaultError,
    InfiniteData<OptionsInfiniteQueryData>,
    QueryKey,
    number | undefined
  >({
    queryKey: apiPath ? [...apiPath.split('?'), debouncedSearchKeyword] : [debouncedSearchKeyword],
    queryFn: ({ signal, pageParam }) => {
      return executeAxios({
        url: isLabelAsValue
          ? `${apiPath}${apiPath?.includes('?') ? '&' : '?'}page=${pageParam}&pageSize=${infiniteQueryPageSize}${debouncedSearchKeyword ? `&searchQuery=${debouncedSearchKeyword}` : ''}`
          : `${apiPath}${apiPath?.includes('?') ? '&' : '?'}page=${pageParam}&pageSize=${infiniteQueryPageSize}${selectedValue ? `&preSelected=${selectedValue}` : ''}${debouncedSearchKeyword ? `&searchQuery=${debouncedSearchKeyword}` : ''}`,
        method: 'GET',
        signal
      })
    },
    enabled: isEnabled,
    initialPageParam: 1,
    getNextPageParam
  })

  // Effects
  React.useEffect(() => {
    if (!fieldData.config?.apiPath) {
      return
    }

    const newQueryPath = dependencyFieldCodes.reduce<string>((result, code) => {
      const value = dependencyFieldsValue[code]
      if (value == null) {
        return result
      }
      return result.replace(`{${code}}`, value)
    }, fieldData.config.apiPath)

    setApiPath(newQueryPath)
    setIsEnabled(!newQueryPath?.includes('/{'))
  }, [dependencyFieldCodes, dependencyFieldsValue, fieldData])

  // Memos
  const options = React.useMemo<Option[]>(() => {
    if (!isEnabled) {
      return []
    }
    return optionsInfiniteQuery.data?.pages.flatMap((page) => page.responseData.rows) ?? []
  }, [isEnabled, optionsInfiniteQuery.data])

  return {
    optionsInfiniteQuery,
    options,
    searchKeyword,
    setSearchKeyword
  }
}

import { toDate } from 'date-fns'
import { isValidPhoneNumber } from 'react-phone-number-input'
import z, { type ZodArray, type ZodNullable, type ZodNumber, type ZodPipe, type ZodString, type ZodType } from 'zod'
import type { UploadedFile } from '@/components/molecules/file-upload'
import type { FormValue, SmartFormData } from './base'

// Schema options
export type SchemaOptions<T = FormValue> = {
  hiddenFields?: Record<string, boolean | undefined>
  slots?: Record<string, z.ZodTypeAny>
  refinement?: (arg: T, ctx: z.core.$RefinementCtx<T>) => void | Promise<void>
}

// Get form schema
export const getFormSchema = (formData: SmartFormData, schemaOptions?: SchemaOptions) => {
  const shape: Record<string, ZodType> = {}

  const passwordConfirmationFields: Array<{
    code: string
    referenceFields: NonNullable<
      NonNullable<SmartFormData['templates'][number]['fields'][number]['config']>['referenceFields']
    >
  }> = []

  formData.templates.forEach((template) => {
    template.fields.forEach((field) => {
      const { code, type, config: { validation, isPasswordConfirmation, referenceFields } = {} } = field

      // Hidden fields
      if (schemaOptions?.hiddenFields?.[code]) return

      // Visible fields
      switch (type) {
        // input | textarea | phone-number | autocomplete | autocomplete-with-infinite-query | editor (string)
        case 'input':
        case 'textarea':
        case 'phone-number':
        case 'autocomplete-with-options':
        case 'autocomplete-with-query':
        case 'autocomplete-with-infinite-query':
        case 'editor': {
          let fieldSchema: ZodString | ZodPipe<ZodType> = z.string().trim()

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Email
          if (validation?.email) {
            fieldSchema = fieldSchema.refine((value) => {
              try {
                if (!validation.required && !value) {
                  return true
                }
                return Boolean(z.email().parse(value))
              } catch {
                return false
              }
            }, validation.email.message)

            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.min(1, validation.required.message)
          }

          // Min
          if (validation.min) {
            fieldSchema = fieldSchema.min(validation.min.value as number, validation.min.message)
          }

          // Max
          if (validation.max) {
            fieldSchema = fieldSchema.max(validation.max.value as number, validation.max.message)
          }

          // Regex
          if (validation.regex) {
            const value = validation.regex.value as {
              pattern: string
              flags: string
            }
            fieldSchema = fieldSchema.regex(new RegExp(value.pattern, value.flags), validation.regex.message)
          }

          // Phone
          if (validation.phone) {
            fieldSchema = fieldSchema.refine(
              (value) => (value ? isValidPhoneNumber(value) : true),
              validation.phone.message
            )
          }

          shape[code] = fieldSchema
          break
        }

        // password (string)
        case 'password': {
          let fieldSchema: ZodString | ZodPipe<ZodType> = z.string().trim()

          if (isPasswordConfirmation) {
            if (referenceFields && referenceFields.length > 0) {
              passwordConfirmationFields.push({
                code,
                referenceFields
              })
            }

            shape[code] = fieldSchema
            break
          }

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.min(1, validation.required.message)
          }

          // Min
          if (validation.min) {
            fieldSchema = fieldSchema.min(validation.min.value as number, validation.min.message)
          }

          // Max
          if (validation.max) {
            fieldSchema = fieldSchema.max(validation.max.value as number, validation.max.message)
          }

          // Regex
          if (validation.regex) {
            const value = validation.regex.value as {
              pattern: string
              flags: string
            }
            fieldSchema = fieldSchema.regex(new RegExp(value.pattern, value.flags), validation.regex.message)
          }

          shape[code] = fieldSchema
          break
        }

        // select-with-options | select-with-query | select-with-infinite-query | radio (string)
        case 'select-with-options':
        case 'select-with-query':
        case 'select-with-infinite-query':
        case 'radio': {
          let fieldSchema: ZodNullable<ZodString> | ZodPipe<ZodNullable<ZodString>> = z.string().trim().nullable()

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.refine((value) => value != null, validation.required.message)
          }

          shape[code] = fieldSchema
          break
        }

        // number (string | number)
        case 'number': {
          let fieldSchema: ZodNumber = z.number()

          if (!validation) {
            shape[code] = z.preprocess((value) => (Number.isNaN(Number(value)) ? 0 : Number(value)), fieldSchema)
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.positive(validation.required.message)
          }

          // Min
          if (validation.min) {
            fieldSchema = fieldSchema.gte(validation.min.value as number, validation.min.message)
          }

          // Max
          if (validation.max) {
            fieldSchema = fieldSchema.lte(validation.max.value as number, validation.max.message)
          }

          shape[code] = z.preprocess((value) => (Number.isNaN(Number(value)) ? 0 : Number(value)), fieldSchema)
          break
        }

        // multi-select-with-options | multi-select-with-query | multi-select-with-infinite-query (string[])
        case 'multi-select-with-options':
        case 'multi-select-with-query':
        case 'multi-select-with-infinite-query': {
          let fieldSchema: ZodArray<ZodString> = z.array(z.string())

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.min(1, validation.required.message)
          }

          shape[code] = fieldSchema
          break
        }

        // date (iso string | Date)
        case 'date': {
          if (!validation) {
            shape[code] = z.codec(z.union([z.iso.datetime(), z.date()]).nullable(), z.iso.datetime().nullable(), {
              decode: (value) => (value ? (typeof value === 'string' ? value : value.toISOString()) : null),
              encode: (value) => (value ? toDate(value) : null)
            })
            break
          }

          // Required
          if (validation.required) {
            shape[code] = z.codec(
              z.union([z.iso.datetime(), z.date()]).nullable(),
              z.iso.datetime().nullable().refine(Boolean, validation.required.message),
              {
                decode: (value) => (value ? (typeof value === 'string' ? value : value.toISOString()) : null),
                encode: (value) => (value ? toDate(value) : null)
              }
            )
            break
          }
          break
        }

        // checkbox (boolean)
        case 'checkbox': {
          shape[code] = z.boolean()
          break
        }

        // file (File | UploadedFile | null)
        case 'file': {
          let fieldSchema: ZodType<File | UploadedFile | null> | ZodPipe<ZodType<File | UploadedFile | null>> =
            z.custom<File | UploadedFile | null>()

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.refine((value) => Boolean(value), validation.required.message)
          }

          shape[code] = fieldSchema
          break
        }

        // multi-file (Array<File | UploadedFile>)
        case 'multi-file': {
          let fieldSchema: ZodArray<ZodType<File | UploadedFile>> | ZodPipe<ZodArray<ZodType<File | UploadedFile>>> =
            z.array(z.custom<File | UploadedFile>())

          if (!validation) {
            shape[code] = fieldSchema
            break
          }

          // Required
          if (validation.required) {
            fieldSchema = fieldSchema.refine((value) => value.length > 0, validation.required.message)
          }

          shape[code] = fieldSchema
          break
        }

        // Slot
        case 'slot': {
          const slotFieldSchema = schemaOptions?.slots?.[code]
          if (slotFieldSchema) {
            shape[code] = slotFieldSchema
          }
          break
        }
      }
    })
  })

  let schema = z.object(shape)

  if (passwordConfirmationFields.length > 0) {
    schema = schema.superRefine((arg, ctx) => {
      passwordConfirmationFields.forEach((passwordConfirmationField) => {
        const { code, referenceFields } = passwordConfirmationField
        const referenceField = referenceFields[0]
        if (arg[code] !== arg[referenceField.code]) {
          ctx.addIssue({
            code: 'custom',
            message: referenceField.message,
            path: [code]
          })
        }
      })
    })
  }

  if (schemaOptions?.refinement) {
    schema = schema.superRefine(schemaOptions.refinement)
  }

  return schema
}

import type { FormValue, SmartFormData, SmartFormFieldType } from './base'

// Default field values
export const defaultFieldValues: Record<SmartFormFieldType, string | number | boolean | null | string[]> = {
  input: '', // string
  textarea: '', // string
  'phone-number': '', // string
  number: '', // string | number
  password: '', // string
  'select-with-options': null, // string | null
  'select-with-query': null, // string | null
  'select-with-infinite-query': null, // string | null
  'multi-select-with-options': [], // string[]
  'multi-select-with-query': [], // string[]
  'multi-select-with-infinite-query': [], // string[]
  'autocomplete-with-options': '', // string
  'autocomplete-with-query': '', // string
  'autocomplete-with-infinite-query': '',
  date: null, // Date | null
  checkbox: false, // boolean
  radio: null, // string | null
  file: null, // File | ApiFile | null
  'multi-file': [], // File[] | ApiFile[]
  editor: '', // string
  label: null,
  slot: null
} as const

// Get default form value
export const getDefaultFormValue = <T extends FormValue>(formData: SmartFormData, slots?: T): T => {
  const defaultValue: Record<string, unknown> = {}
  formData.templates.forEach((template) => {
    template.fields.forEach((field) => {
      // LABEL fields
      if (field.type === 'label') {
        return
      }

      // Other fields
      defaultValue[field.code] = slots?.[field.code] ?? defaultFieldValues[field.type]
    })
  })
  return defaultValue as T
}

